inline constexpr const SkyboxDef* findSkybox(std::string_view id) {
    for (const auto& sky : SkyboxCatalog)
        if (sky.id == id) return &sky;
    return nullptr;
}
inline constexpr bool terrainSkybox(std::string_view id) {
    const auto* sky = findSkybox(id);
    return sky && sky->terrain;
}
